    max(case when event_date >= lo_l14d then p_max_event_timestamp_is_android end) as max_event_timestamp_is_android_l14d,
    max(p_max_event_timestamp_is_android) as max_event_timestamp_is_android_l30d,
    max(case when event_date >= lo_l7d then p_max_event_timestamp_is_others end) as max_event_timestamp_is_others_l7d,
    max(case when event_date >= lo_l14d then p_max_event_timestamp_is_others end) as max_event_timestamp_is_others_l14d,
    max(p_max_event_timestamp_is_others) as max_event_timestamp_is_others_l30d,
    max(case when event_date >= lo_l7d then p_max_event_timestamp_is_login_success end) as max_event_timestamp_is_login_success_l7d,
    max(case when event_date >= lo_l14d then p_max_event_timestamp_is_login_success end) as max_event_timestamp_is_login_success_l14d,
    max(p_max_event_timestamp_is_login_success) as max_event_timestamp_is_login_success_l30d,
    max(case when event_date >= lo_l7d then p_max_event_timestamp_is_login_success_is_ios end) as max_event_timestamp_is_login_success_is_ios_l7d,
    max(case when event_date >= lo_l14d then p_max_event_timestamp_is_login_success_is_ios end) as max_event_timestamp_is_login_success_is_ios_l14d,
    max(p_max_event_timestamp_is_login_success_is_ios) as max_event_timestamp_is_login_success_is_ios_l30d,
    max(case when event_date >= lo_l7d then p_max_event_timestamp_is_login_success_is_android end) as max_event_timestamp_is_login_success_is_android_l7d,
    max(case when event_date >= lo_l14d then p_max_event_timestamp_is_login_success_is_android end) as max_event_timestamp_is_login_success_is_android_l14d,
    max(p_max_event_timestamp_is_login_success_is_android) as max_event_timestamp_is_login_success_is_android_l30d,
    max(case when event_date >= lo_l7d then p_max_event_timestamp_is_login_success_is_others end) as max_event_timestamp_is_login_success_is_others_l7d,
    max(case when event_date >= lo_l14d then p_max_event_timestamp_is_login_success_is_others end) as max_event_timestamp_is_login_success_is_others_l14d,
    max(p_max_event_timestamp_is_login_success_is_others) as max_event_timestamp_is_login_success_is_others_l30d,
    max(case when event_date >= lo_l7d then p_max_event_timestamp_is_login_failed end) as max_event_timestamp_is_login_failed_l7d,
    max(case when event_date >= lo_l14d then p_max_event_timestamp_is_login_failed end) as max_event_timestamp_is_login_failed_l14d,
    max(p_max_event_timestamp_is_login_failed) as max_event_timestamp_is_login_failed_l30d,
    max(case when event_date >= lo_l7d then p_max_event_timestamp_is_login_failed_is_ios end) as max_event_timestamp_is_login_failed_is_ios_l7d,
    max(case when event_date >= lo_l14d then p_max_event_timestamp_is_login_failed_is_ios end) as max_event_timestamp_is_login_failed_is_ios_l14d,
    max(p_max_event_timestamp_is_login_failed_is_ios) as max_event_timestamp_is_login_failed_is_ios_l30d,
    max(case when event_date >= lo_l7d then p_max_event_timestamp_is_login_failed_is_android end) as max_event_timestamp_is_login_failed_is_android_l7d,
    max(case when event_date >= lo_l14d then p_max_event_timestamp_is_login_failed_is_android end) as max_event_timestamp_is_login_failed_is_android_l14d,
    max(p_max_event_timestamp_is_login_failed_is_android) as max_event_timestamp_is_login_failed_is_android_l30d,
    max(case when event_date >= lo_l7d then p_max_event_timestamp_is_login_failed_is_others end) as max_event_timestamp_is_login_failed_is_others_l7d,
    max(case when event_date >= lo_l14d then p_max_event_timestamp_is_login_failed_is_others end) as max_event_timestamp_is_login_failed_is_others_l14d,
    max(p_max_event_timestamp_is_login_failed_is_others) as max_event_timestamp_is_login_failed_is_others_l30d,

    max(case when _n_rows > 0 then event_date end) as _rollup_last_event_date
from partials
group by safe_id
having sum(_n_rows) > 0
